def pindahkan_dokumen_ke_storage_privat(apps, schema_editor):
    Dokumen = apps.get_model('toko', 'DokumenTitipJual')
    sumber = default_storage
    tujuan = katalog_mbg.storage.PrivateTitipJualStorage()
    for dokumen in Dokumen.objects.exclude(file='').iterator():
        nama = dokumen.file.name
        if not tujuan.exists(nama):
            if not sumber.exists(nama):
                raise RuntimeError(
                    f'Dokumen Titip-Jual {dokumen.pk} tidak ditemukan di storage lama: {nama}'
                )
            with sumber.open(nama, 'rb') as berkas:
                nama_tujuan = tujuan.save(nama, berkas)
        else:
            nama_tujuan = nama

        if nama_tujuan != nama:
            dokumen.file.name = nama_tujuan
            dokumen.save(update_fields=['file'])
        if sumber.exists(nama):
            sumber.delete(nama)
            if sumber.exists(nama):
                raise RuntimeError(
                    f'Dokumen Titip-Jual {dokumen.pk} masih dapat diakses dari storage lama: {nama}'
                )


